from pathlib import Path
from lxml import html as H
p=Path('dist/agri/index.html');d=H.fromstring(p.read_text())
def settext(el,text):
 for child in list(el):el.remove(child)
 el.text=text
home=d.get_element_by_id('home');settext(home.xpath('.//h1')[0],'خطة محتوى بتوضّح قيمة أجري إكسبو للشركات والزوّار.')
start=d.get_element_by_id('start');settext(start.xpath('.//h2')[0],'هنقدّم إيه؟ ولمين؟');start.xpath('.//summary')[0].text='الجمهور والخطوة اللي بنستهدفها'
items=[('إبراز قيمة المعرض','نشجّع الشركات على المشاركة والزوّار على تسجيل زيارتهم، من خلال اللي المعرض بيقدّمه لكل طرف.'),('تلات مسارات','شركات بتفكّر تشارك، وزوّار ومتخصصين، ورعاة وشركات مشاركة.'),('تصميمات وريلز','بنشرح قيمة المعرض، ونعرض المنتجات، ونقدّم تجارب الشركات.'),('للشركات','نوضّح قيمة المشاركة، ونعرض المنتجات، ونفتح باب التواصل لحجز الأجنحة.'),('للزوّار','اكتشاف المنتجات، ومقابلة الشركات والمتخصصين، والتخطيط للزيارة.'),('للمشاركين والرعاة','نقدّم تجارب الشركات ومنتجاتها، ومنها أجرو سيف بصفتها الراعي الماسي.')]
for el,(title,body) in zip(start.xpath('.//article'),items):el.xpath('.//h3')[0].text=title;el.xpath('.//p')[0].text=body
start.xpath('.//a[contains(@class,"strategy-link")]')[0].text='اطّلع على الاستراتيجية كاملة ↗'
s=d.get_element_by_id('samples');ps=s.xpath('./div[contains(@class,"section-title")]/p');ps[0].text='٦ تصميمات من ضمنها كاروسيل واحد · ٣ ريلز بتصوير جديد';ps[1].text='اختار أي نموذج وشوف فكرته وهدفه ونصوصه. اسحب الصور جوّه العرض عشان تستكشف التفاصيل.'
for el,(h,t) in zip(s.xpath('.//div[contains(@class,"week-story")]/article'),[('بنفتح باب التعارف والمشاركة.','شبكة الأعمال، ولقاء الشركات، وتجربة مشارك، ومنتجات الراعي الماسي.'),('بنقرّب تجربة المعرض من الجمهور.','عرض الشركات، والحوار جوّه المعرض، والجلسات العلمية، والمنتجات.')]):el.xpath('./h3')[0].text=h;el.xpath('./p')[0].text=t
w=d.get_element_by_id('workflow');w.xpath('.//h2')[0].text='إزاي بنشتغل؟'
for el,t in zip(w.xpath('.//article/p'),['نحدد الشركات والمتحدثين ووجه المعرض والمنتجين ومواعيد التصوير.','تصوير الريلز، وتجهيز التصميمات وشرايح الكاروسيل.','مراجعة بيانات الشركات والمنتجات، والنصوص والروابط، والصورة والصوت.','نثبّت المواعيد حسب جاهزية المواد، وبالتنسيق مع فريق المعرض.','نقرا تفاعل الجمهور في آخر كل أسبوع.']):el.text=t
d.xpath('//header//a[@href="#workflow"]')[0].text='إزاي بنشتغل؟'
a=d.get_element_by_id('deliverables');a.xpath('./div[contains(@class,"section-title")]/p')[0].text='كل شهر بيبدأ بخطة واضحة، قبل ما يبدأ إنتاج أي قطعة.'
for el,t in zip(a.xpath('.//article/p'),['نحدد أهداف الشهر ونربطها بالأهداف التسويقية للعلامة التجارية.','نحدد الموضوعات الأساسية ونوزّع المحتوى عليها.','نطوّر أفكار تليق بالجمهور وبهوية العلامة التجارية.','نحدد استخدام البوستات الثابتة والكاروسيل والموشن جرافيك والريلز في حدود الأعداد المتفق عليها.','نحدد الرسالة الأساسية، وطريقة تناول كل فكرة.','نحدد المعالجة الإبداعية والشكل البصري المبدئي.','ننظّم مواعيد النشر المقترحة والمنصات في جدول شهري.','نحدد الخطوة المطلوبة من الجمهور مع كل قطعة محتوى.']):el.text=t
p.write_text('<!doctype html>'+H.tostring(d,encoding='unicode',method='html'))
